import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load GLB mesh
  const gltf = ctx.glbLoader.load(config.meshUrl);
  group.add(gltf.scene);

  // Apply scene placement
  const pos = config.position || config.scenePosition || [0, 0, 0];
  const rot = config.rotation || config.sceneRotation || [0, 0, 0];
  const scale = config.scale || config.sceneScale || [1, 1, 1];

  group.position.set(pos[0], pos[1], pos[2]);
  group.rotation.set(rot[0], rot[1], rot[2]);
  group.scale.set(scale[0], scale[1], scale[2]);

  // Store original Y for hover animation
  const originalY = group.position.y;

  // Track timelines for cleanup
  const timelines = [];
  let activeTimeline = null;

  // Event handlers
  const handlers = {
    hover: () => {
      if (activeTimeline) activeTimeline.kill();

      // Rise-in: +0.15 y, power3.out, 0.7s
      activeTimeline = gsap.to(group.position, {
        y: originalY + 0.15,
        duration: 0.7,
        ease: 'power3.out'
      });
      timelines.push(activeTimeline);
    },

    unhover: () => {
      if (activeTimeline) activeTimeline.kill();

      // Return to original position
      activeTimeline = gsap.to(group.position, {
        y: originalY,
        duration: 0.7,
        ease: 'power3.out'
      });
      timelines.push(activeTimeline);
    },

    click: () => {
      // Emit click event
      if (config.behaviors) {
        const clickBehavior = config.behaviors.find(b => b.event === 'click');
        if (clickBehavior && clickBehavior.effect.startsWith('emit:')) {
          const eventName = clickBehavior.effect.replace('emit:', '');
          if (ctx.events && typeof ctx.events.emit === 'function') {
            ctx.events.emit(eventName);
          }
        }
      }
    }
  };

  group.userData.handlers = handlers;

  // Cleanup function
  group.userData.cleanup = () => {
    // Kill all GSAP timelines
    timelines.forEach(tl => tl.kill());
    if (activeTimeline) activeTimeline.kill();

    // Dispose materials and geometries
    gltf.scene.traverse(child => {
      if (child instanceof THREE.Mesh) {
        if (child.geometry) child.geometry.dispose();
        if (child.material) {
          if (Array.isArray(child.material)) {
            child.material.forEach(mat => mat.dispose());
          } else {
            child.material.dispose();
          }
        }
      }
    });

    // Remove from parent
    if (group.parent) group.parent.remove(group);
  };

  return group;
}
